def out_file(directory, name):
    """Build an output path, creating the directory the first time it is used."""
    if not os.path.isdir(directory):
        os.makedirs(directory, exist_ok=True)
    return os.path.join(directory, name)


def cv_folds(y, numFolds):
    """Clamp the requested fold count so that stratified CV is always possible."""
    counts = np.unique(np.asarray(y), return_counts=True)[1]
    if len(counts) == 0:
        return max(int(numFolds), 2)
    return int(max(2, min(int(numFolds), int(counts.min()))))


def weighted_roc_auc(y_true, y_prob):
    """Weighted ROC-AUC that works for both binary and multi-class problems."""
    y_prob = np.asarray(y_prob)
    n_classes = len(np.unique(np.asarray(y_true)))

    if y_prob.ndim == 1:
        return roc_auc_score(y_true, y_prob, average='weighted')
    if y_prob.shape[1] == 1:
        return roc_auc_score(y_true, y_prob[:, 0], average='weighted')
    if n_classes <= 2 and y_prob.shape[1] == 2:
        return roc_auc_score(y_true, y_prob[:, 1], average='weighted')
    return roc_auc_score(y_true, y_prob, multi_class='ovr', average='weighted')


def score_model(estimator, X, y):
    """Weighted ROC-AUC of a fitted estimator, preferring probability estimates."""
    if hasattr(estimator, 'predict_proba'):
        return weighted_roc_auc(y, estimator.predict_proba(X))
    return weighted_roc_auc(y, estimator.decision_function(X))


